lab.testCode:
int main(void) {
  RRJob jobs[] = {{'A', 5}, {'B', 3}};
  Turn timeline[8] = {0};
  int turns = round_robin(jobs, 2, 2, timeline, 8);
  Turn expected[] = {{'A', 2}, {'B', 2}, {'A', 2}, {'B', 1}, {'A', 1}};
  int same = turns == 5;
  int ticks = 0;
  for (int i = 0; i < turns && i < 8; ++i) {
    ticks += timeline[i].ticks;
