                  const char thread_b[], int b_count,
                  char schedules[][8], int capacity) {
  // Each output row must preserve both threads' internal order.
  // TODO: use recursion or an explicit stack.
  (void)thread_a;
  (void)a_count;
  (void)thread_b;
  (void)b_count;
  (void)schedules;
  (void)capacity;
  return 0;
}

lab.testCode:
#include <string.h>

int main(void) {
  char schedules[8][8] = {{0}};
  int count = interleavings("AB", 2, "ab", 2, schedules, 8);
  int has_alternating = 0;
  int preserves_order = 1;
  for (int i = 0; i < count && i < 8; ++i) {
    if (strcmp(schedules[i], "AaBb") == 0) has_alternating = 1;
    char *A = strchr(schedules[i], 'A');
    char *B = strchr(schedules[i], 'B');
    char *a = strchr(schedules[i], 'a');
    char *b = strchr(schedules[i], 'b');
    if (!A || !B || !a || !b || A > B || a > b) preserves_order = 0;
  }
  SL_CHECK(count == 6, "number of schedules");
  SL_CHECK(has_alternating, "contains alternating schedule");
  SL_CHECK(preserves_order, "preserves per-thread order");
  printf("__STUDYLAB_RESULT__ %d %d\n", study_lab_passed, study_lab_total);
  return study_lab_passed == study_lab_total ? 0 : 1;
}

